insert into public.sources (id, url, title, publisher, level, consulted_on) values
  ('30000003-0000-4000-8100-000000000001', 'https://empleo.enaire.es/empleo/mostrarBinarioSharepoint.jsp?urlPDF=.nav.es/portal/empleo/Lists/Ocupaciones/Attachments/177/3.%20Meteorolog%EDa.pdf', 'ENAIRE · Temario Tema 3: Conceptos básicos de meteorología', 'ENAIRE', 'A', '2026-10-19')
insert into public.study_blocks (id, topic_id, temario_point, exam_part, sort, title, objectives, key_idea, body_md, example_md, trap_md, exam_tip_md, mnemonic_md, source_id, source_pages, reviewed) values
  ('30000003-0000-4000-8101-000000000001', '00000000-0000-4000-8000-000000006003', '1. La Meteorología en el contexto aeronáutico (1.1 a 1.3)', 'conocimientos', 1, 'El servicio meteorológico aeronáutico', array['Qué diferencia hay entre tiempo y clima y qué da un pronóstico.', 'Qué centros mundiales y regionales hay y cuántos son.', 'Qué oficinas de AEMET dan servicio en España y qué producen.'], 'El Anexo 3 de la OACI regula el servicio meteorológico, que se presta en cadena: centros mundiales, regionales, de FIR y de aeródromo.', '**Tiempo** es el estado de la atmósfera en un instante; **clima**, la síntesis estadística a largo plazo de un lugar (OMM). La información es **observada** o **prevista**, y el pronóstico da el valor **más probable** del periodo.
insert into public.block_questions (id, block_id, role, stem, options, correct_index, explanation, source_pages, origin, reviewed) values
  ('30000003-0000-4000-8102-000000000001', '30000003-0000-4000-8101-000000000001', 'previa', 'Según la OMM, ¿qué diferencia hay entre tiempo y clima?', '["El tiempo es estadística a largo plazo; el clima, un instante", "El tiempo es un instante; el clima, estadística a largo plazo", "El tiempo mide la temperatura; el clima, la precipitación", "Son sinónimos en la meteorología aeronáutica de la OACI"]'::jsonb, 1, 'La OMM define el tiempo como el estado de la atmósfera en un instante dado y el clima como la síntesis de las condiciones de un lugar con estadísticas a largo plazo (p. 4).', 'p. 4', 'practica', false),
  ('30000003-0000-4000-8102-000000000002', '30000003-0000-4000-8101-000000000001', 'comprobacion', '¿Cuántos Centros de Avisos de Cenizas Volcánicas (VAAC) hay?', '["Siete", "Ocho", "Nueve", "Diez"]'::jsonb, 2, 'Hay nueve VAAC, con vigilancia las 24 horas. Los TCAC son siete y los CMRE, ocho (p. 7).', 'p. 7', 'practica', false),
  ('30000003-0000-4000-8102-000000000003', '30000003-0000-4000-8101-000000000001', 'comprobacion', '¿Qué oficinas elaboran los TAF, los TREND y los avisos de aeródromo?', '["Las estaciones meteorológicas aeronáuticas", "Los centros mundiales de pronóstico de área", "Las oficinas meteorológicas de aeródromo", "Las oficinas de vigilancia meteorológica"]'::jsonb, 2, 'Las OMAe hacen la vigilancia y las predicciones de aeródromo (TAF, TREND y avisos). Las EMAe hacen las observaciones (METAR y SPECI) (p. 8).', 'p. 8', 'practica', false),
  ('30000003-0000-4000-8102-000000000004', '30000003-0000-4000-8101-000000000001', 'comprobacion', '¿A qué horas se lanzan los globos sonda de los sondeos aerológicos?', '["A las 06 y a las 18 UTC", "Cada hora, junto al METAR", "A las 10 y a las 22 UTC", "A las 00 y a las 12 UTC"]'::jsonb, 3, 'Los sondeos miden presión, temperatura y humedad en la vertical, con globos lanzados a las 00 y a las 12 UTC (p. 9).', 'p. 9', 'practica', false),
  ('30000003-0000-4000-8102-000000000005', '30000003-0000-4000-8101-000000000002', 'previa', '¿Qué gas es el más abundante en el aire seco?', '["El nitrógeno", "El oxígeno", "El vapor de agua", "El argón"]'::jsonb, 0, 'El aire seco cerca del nivel del mar tiene un 78 % de nitrógeno, un 21 % de oxígeno y un 1 % de otros gases (p. 10).', 'p. 10', 'practica', false),
  ('30000003-0000-4000-8102-000000000006', '30000003-0000-4000-8101-000000000002', 'comprobacion', '¿Entre qué valores varía el vapor de agua en la atmósfera?', '["Entre el 0,2 % y el 3 %", "Entre el 1 % y el 21 %", "Entre el 3 % y el 10 %", "Entre el 0 % y el 1 %"]'::jsonb, 0, 'El vapor de agua puede variar entre el 0,2 % y el 3 %, y está casi todo en la troposfera (p. 11).', 'p. 11', 'practica', false),
  ('30000003-0000-4000-8102-000000000007', '30000003-0000-4000-8101-000000000002', 'comprobacion', 'Un volumen de aire está saturado. ¿Qué humedad relativa tiene?', '["Del 100 %", "Del 78 %", "Del 70 %", "Del 50 %"]'::jsonb, 0, 'Cuando el aire está saturado, su humedad relativa es del 100 % (p. 17).', 'p. 17', 'practica', false),
  ('30000003-0000-4000-8102-000000000008', '30000003-0000-4000-8101-000000000002', 'comprobacion', '¿Qué es el punto de rocío?', '["La temperatura a la que hay que calentar el aire, a presión constante, para secarlo", "La presión a la que hay que comprimir el aire, a temperatura constante, para saturarlo", "La temperatura a la que hay que enfriar el aire, a presión constante, para saturarlo", "La temperatura a la que el vapor de agua pasa a hielo directamente, por sublimación"]'::jsonb, 2, 'El punto de rocío es la temperatura a la que hay que enfriar el aire, manteniendo la presión constante, para que su humedad relativa sea del 100 % (p. 18).', 'p. 18', 'practica', false),
  ('30000003-0000-4000-8102-000000000009', '30000003-0000-4000-8101-000000000003', 'previa', '¿Qué le ocurre a la presión atmosférica al aumentar la altitud?', '["Aumenta, porque el aire se comprime", "No cambia, porque actúa en todas direcciones", "Disminuye, porque hay menos aire encima", "Aumenta, porque el aire está más frío"]'::jsonb, 2, 'Al subir disminuye la altura de la columna de aire que hay encima y, por tanto, su peso: la presión baja con la altitud (p. 12).', 'p. 12', 'practica', false),
  ('30000003-0000-4000-8102-000000000010', '30000003-0000-4000-8101-000000000003', 'comprobacion', '¿Qué equivalencia de presión es correcta?', '["1 atm = 1013,25 mm Hg = 760 hPa", "1 atm = 760 mm Hg = 1000 hPa", "1 atm = 76 mm Hg = 1013,25 hPa", "1 atm = 760 mm Hg = 1013,25 hPa"]'::jsonb, 3, 'Una atmósfera equivale a 760 mm de mercurio y a 1013,25 hPa (mb), según el experimento de Torricelli (p. 14).', 'p. 14', 'practica', false),
  ('30000003-0000-4000-8102-000000000011', '30000003-0000-4000-8101-000000000003', 'comprobacion', '¿A cuántos grados centígrados equivalen 50 ºF?', '["18 ºC", "28 ºC", "82 ºC", "10 ºC"]'::jsonb, 3, 'C = 5/9 · (F − 32) = 5/9 · (50 − 32) = 5/9 · 18 = 10 ºC (p. 16).', 'p. 16', 'practica', false),
  ('30000003-0000-4000-8102-000000000012', '30000003-0000-4000-8101-000000000003', 'comprobacion', 'A presión constante, ¿cómo es el aire más caliente?', '["Más denso, y su columna es más baja", "Menos denso, y su columna es más alta", "Igual de denso, porque la presión no cambia", "Más denso, y su columna es más alta"]'::jsonb, 1, 'A presión constante, el aire es menos denso cuanto mayor es su temperatura, y la columna más caliente es la más alta (p. 17).', 'p. 17', 'practica', false),
  ('30000003-0000-4000-8102-000000000013', '30000003-0000-4000-8101-000000000004', 'previa', '¿En qué capa ocurren casi todos los fenómenos meteorológicos?', '["En la estratosfera", "En la mesosfera", "En la troposfera", "En la ionosfera"]'::jsonb, 2, 'La troposfera contiene casi todo el vapor de agua y la mayor parte de la masa, y en ella hay movimientos verticales muy marcados (p. 18).', 'p. 18', 'practica', false),
  ('30000003-0000-4000-8102-000000000014', '30000003-0000-4000-8101-000000000004', 'comprobacion', '¿A qué altura media está la tropopausa en latitudes altas?', '["Unos 8 km", "Unos 12 km", "Unos 18 km", "Unos 50 km"]'::jsonb, 0, 'La tropopausa está a unos 8 km en latitudes altas, 12 km en latitudes medias y 18 km en latitudes bajas (p. 18).', 'p. 18', 'practica', false),
  ('30000003-0000-4000-8102-000000000015', '30000003-0000-4000-8101-000000000004', 'comprobacion', 'Según el temario, ¿qué significa un gradiente térmico vertical positivo?', '["Que la temperatura aumenta con la altura", "Que la temperatura no varía con la altura", "Que la presión aumenta con la altura", "Que la temperatura desciende con la altura"]'::jsonb, 3, 'Gradiente positivo: la temperatura desciende con la altura. Gradiente negativo: la temperatura aumenta con la altura (p. 15).', 'p. 15', 'practica', false),
  ('30000003-0000-4000-8102-000000000016', '30000003-0000-4000-8101-000000000004', 'comprobacion', '¿Qué tiempo se asocia al aire inestable?', '["Nubes desarrolladas, chubascos y turbulencia", "Cielo despejado y nieblas en capas bajas", "Nubes estratiformes y humo sin dispersar", "Calma, nieblas y ausencia de nubes altas"]'::jsonb, 0, 'El aire inestable da nubes a veces muy desarrolladas, chubascos y turbulencia, con buena visibilidad fuera de ellos. Las otras opciones describen aire estable (p. 21).', 'p. 21', 'practica', false),
  ('30000003-0000-4000-8102-000000000017', '30000003-0000-4000-8101-000000000005', 'previa', '¿Qué temperatura tiene la atmósfera ISA a nivel del mar?', '["0 ºC", "20 ºC", "10 ºC", "15 ºC"]'::jsonb, 3, 'La ISA tiene a nivel del mar 15 ºC (288,15 K), 1013,25 hPa y 1,2250 kg/m³ (p. 21).', 'p. 21', 'practica', false),
  ('30000003-0000-4000-8102-000000000018', '30000003-0000-4000-8101-000000000005', 'comprobacion', 'En la atmósfera ISA, ¿qué temperatura corresponde a 4.000 ft?', '["7 ºC", "9 ºC", "3 ºC", "11 ºC"]'::jsonb, 0, 'Con 15 ºC a nivel del mar y un descenso de 2 ºC cada 1.000 ft, a 4.000 ft hay 15 − 8 = 7 ºC (pp. 21-22).', 'pp. 21-22', 'practica', false),
  ('30000003-0000-4000-8102-000000000019', '30000003-0000-4000-8101-000000000005', 'comprobacion', 'Una aeronave está en tierra con el altímetro calado en QFE. ¿Qué indica?', '["La elevación del aeródromo sobre el nivel del mar", "La altitud respecto a la superficie de 1013,25 hPa", "El nivel de vuelo correspondiente al aeródromo", "Cero, porque indica la altura sobre el aeródromo"]'::jsonb, 3, 'Con QFE el altímetro indica altura; en tierra marca cero. Con QNH marcaría la altitud del aeródromo (p. 25).', 'p. 25', 'practica', false),
  ('30000003-0000-4000-8102-000000000020', '30000003-0000-4000-8101-000000000005', 'comprobacion', 'Un aeropuerto está por encima del nivel del mar. ¿Cómo son su QNH y su QFE?', '["El QNH es menor que el QFE", "El QNH y el QFE son iguales", "El QFE es siempre 1013,25 hPa", "El QNH es mayor que el QFE"]'::jsonb, 3, 'Si el aeropuerto está por encima del nivel del mar, el QNH es mayor que el QFE; al nivel del mar coinciden y por debajo, el QNH es menor (p. 25).', 'p. 25', 'practica', false),
  ('30000003-0000-4000-8102-000000000021', '30000003-0000-4000-8101-000000000006', 'previa', '¿En qué se expresan los niveles de vuelo?', '["En miles de metros", "En centenares de pies", "En cientos de metros", "En decenas de pies"]'::jsonb, 1, 'Los niveles de vuelo se expresan en centenares de pies y se miden desde la superficie de 1013,25 hPa (p. 25).', 'p. 25', 'practica', false),
  ('30000003-0000-4000-8102-000000000022', '30000003-0000-4000-8101-000000000006', 'comprobacion', '¿Cuál es la altitud de transición en la CTA de Granada?', '["6.000 ft", "13.000 ft", "7.000 ft", "10.000 ft"]'::jsonb, 2, 'En España hay tres valores: TMA de Madrid, 13.000 ft; CTA de Granada, 7.000 ft; el resto, 6.000 ft (p. 26).', 'p. 26', 'practica', false),
  ('30000003-0000-4000-8102-000000000023', '30000003-0000-4000-8101-000000000006', 'comprobacion', '¿Qué referencia tiene en cuenta la aeronave en la aproximación para el aterrizaje?', '["La altitud de transición", "El nivel de transición", "La capa de transición", "El nivel de vuelo de crucero"]'::jsonb, 1, 'La aeronave tiene en cuenta el nivel de transición en la aproximación y la altitud de transición en el despegue (p. 26).', 'p. 26', 'practica', false),
  ('30000003-0000-4000-8102-000000000024', '30000003-0000-4000-8101-000000000006', 'comprobacion', 'Por encima del nivel de transición, ¿cómo debe estar calado el altímetro?', '["En el QNH del aeródromo", "En el QFE del aeródromo", "En QNE, con 1013,25 hPa", "En el QNH de la estación más cercana"]'::jsonb, 2, 'Por encima del nivel de transición se opera en niveles de vuelo y el altímetro debe estar calado a QNE (p. 26).', 'p. 26', 'practica', false),
  ('30000003-0000-4000-8102-000000000025', '30000003-0000-4000-8101-000000000007', 'previa', '¿De qué tipo es la radiación que emite el Sol?', '["De onda larga", "De onda corta", "De onda media", "De onda ultralarga"]'::jsonb, 1, 'La radiación solar es radiación electromagnética de onda corta. La terrestre es de onda larga (pp. 27-28).', 'pp. 27-28', 'practica', false),
  ('30000003-0000-4000-8102-000000000026', '30000003-0000-4000-8101-000000000007', 'comprobacion', '¿Qué proceso transmite el calor mediante movimientos horizontales de masas de aire?', '["La advección", "La convección", "La conducción", "La radiación"]'::jsonb, 0, 'La advección transmite el calor con movimientos horizontales de masas de aire; la convección origina movimientos verticales (p. 30).', 'p. 30', 'practica', false),
  ('30000003-0000-4000-8102-000000000027', '30000003-0000-4000-8101-000000000007', 'comprobacion', '¿Por qué el mar se calienta y se enfría más despacio que la tierra?', '["Porque el agua refleja toda la radiación solar", "Porque el aire sobre el mar es más denso", "Porque el mar solo absorbe onda larga", "Porque el agua tiene el mayor calor específico"]'::jsonb, 3, 'El agua es la sustancia con mayor calor específico de la naturaleza; por eso los mares se calientan y se enfrían más lentamente (p. 27).', 'p. 27', 'practica', false),
  ('30000003-0000-4000-8102-000000000028', '30000003-0000-4000-8101-000000000007', 'comprobacion', '¿Qué hacen los gases de efecto invernadero con la radiación?', '["Absorben la onda corta y dejan pasar la onda larga", "Reflejan hacia el espacio toda la radiación solar", "Absorben solo la radiación que reflejan las nubes", "Dejan pasar la onda corta y absorben la onda larga"]'::jsonb, 3, 'Son gases transparentes a la onda corta que entra y absorbentes de la onda larga que reemite la Tierra (pp. 28-29).', 'pp. 28-29', 'practica', false),
  ('30000003-0000-4000-8102-000000000029', '30000003-0000-4000-8101-000000000008', 'previa', '¿Hacia dónde desvía la fuerza de Coriolis en el hemisferio sur?', '["Hacia la derecha", "Hacia el ecuador", "Hacia la izquierda", "Hacia el polo sur"]'::jsonb, 2, 'La fuerza de Coriolis desvía a la derecha en el hemisferio norte y a la izquierda en el sur (p. 33).', 'p. 33', 'practica', false),
  ('30000003-0000-4000-8102-000000000030', '30000003-0000-4000-8101-000000000008', 'comprobacion', '¿Qué célula de circulación está entre unos 30º y 60º de latitud?', '["La célula de Hadley", "La célula de Ferrel", "La célula Polar", "La célula de Rossby"]'::jsonb, 1, 'Hadley va del ecuador a unos 30º, Ferrel de 30º a 60º y la Polar de 60º al polo (p. 32).', 'p. 32', 'practica', false),
  ('30000003-0000-4000-8102-000000000031', '30000003-0000-4000-8101-000000000008', 'comprobacion', '¿De dónde soplan los alisios en el hemisferio norte?', '["Del sudeste", "Del noroeste", "Del sudoeste", "Del nordeste"]'::jsonb, 3, 'Los alisios soplan del NE en el hemisferio norte y del SE en el sur, y convergen en la Zona de Convergencia Intertropical (p. 35).', 'p. 35', 'practica', false),
  ('30000003-0000-4000-8102-000000000032', '30000003-0000-4000-8101-000000000008', 'comprobacion', '¿Qué es la subsidencia?', '["El ascenso del aire caliente desde la superficie", "El descenso del aire hacia el suelo en la troposfera", "El choque de dos corrientes de aire en superficie", "La separación horizontal de una masa de aire"]'::jsonb, 1, 'La subsidencia es el descenso del aire hacia el suelo en la troposfera, normalmente de aire frío y denso desde capas medias y altas (p. 35).', 'p. 35', 'practica', false),
  ('30000003-0000-4000-8102-000000000033', '30000003-0000-4000-8101-000000000009', 'previa', '¿En qué sentido gira el viento en un anticiclón del hemisferio norte?', '["En sentido horario", "En sentido antihorario", "Hacia el centro, sin girar", "En sentido variable"]'::jsonb, 0, 'La circulación de un anticiclón es horaria en el hemisferio norte y antihoraria en el sur (p. 36).', 'p. 36', 'practica', false),
  ('30000003-0000-4000-8102-000000000034', '30000003-0000-4000-8101-000000000009', 'comprobacion', '¿Qué diferencia a los ciclones tropicales de los extratropicales?', '["Sus vientos en altura son siempre fuertes", "Sus vientos en altura suelen ser flojos", "Tienen bajas presiones también en altura", "Solo se forman sobre continentes cálidos"]'::jsonb, 1, 'A diferencia de los ciclones extratropicales, en los tropicales los vientos en altura suelen ser flojos; tienen bajas en superficie y altas presiones en altura (p. 37).', 'p. 37', 'practica', false),
  ('30000003-0000-4000-8102-000000000035', '30000003-0000-4000-8101-000000000009', 'comprobacion', '¿Cuántos tipos de masas de aire salen de combinar temperatura y humedad?', '["Cuatro", "Ocho", "Seis", "Dos"]'::jsonb, 1, 'Cuatro tipos por temperatura (ártica, polar, tropical y ecuatorial) por dos por humedad (seca o húmeda) dan 8 tipos (p. 39).', 'p. 39', 'practica', false),
  ('30000003-0000-4000-8102-000000000036', '30000003-0000-4000-8101-000000000009', 'comprobacion', 'Dos masas de aire se encuentran, pero ninguna desplaza a la otra. ¿Qué frente es?', '["Ocluido, con el sector cálido elevado en altura", "Estacionario, con viento paralelo al frente", "Cálido, con el aire caliente sobre el frío", "Frío, con el aire frío avanzando en cuña"]'::jsonb, 1, 'En el frente estacionario no hay desplazamiento y el viento tiende a soplar paralelo al frente, en sentidos opuestos (p. 40).', 'p. 40', 'practica', false),
  ('30000003-0000-4000-8102-000000000037', '30000003-0000-4000-8101-000000000010', 'previa', '¿En cuántas partes (octas) se divide el cielo para estimar la nubosidad?', '["Diez", "Ocho", "Cuatro", "Doce"]'::jsonb, 1, 'El cielo se divide en ocho partes, llamadas octas, y se cuentan las que cubre cada capa (p. 46).', 'p. 46', 'practica', false),
  ('30000003-0000-4000-8102-000000000038', '30000003-0000-4000-8101-000000000010', 'comprobacion', '¿Qué abreviatura indica de 3 a 4 octas de cielo cubierto?', '["FEW", "SCT", "BKN", "OVC"]'::jsonb, 1, 'FEW es 1-2 octas, SCT 3-4, BKN 5-7 y OVC cielo cubierto (p. 46).', 'p. 46', 'practica', false),
  ('30000003-0000-4000-8102-000000000039', '30000003-0000-4000-8101-000000000010', 'comprobacion', 'Hay una capa SCT a 800 ft y otra BKN a 2.500 ft. ¿Dónde está el techo?', '["A 800 ft, la capa más baja", "No hay techo, porque hay una capa SCT", "A 3.300 ft, sumando las dos capas", "A 2.500 ft, la primera capa BKN"]'::jsonb, 3, 'El techo es la base de la capa más baja que cubre más de la mitad del cielo (BKN u OVC) por debajo de 20.000 ft. La capa SCT no cuenta (p. 47).', 'p. 47', 'practica', false),
  ('30000003-0000-4000-8102-000000000040', '30000003-0000-4000-8101-000000000010', 'comprobacion', '¿Qué nubes producen halos alrededor del Sol o de la Luna?', '["Los cirrostratos", "Los altoestratos", "Los cirrocúmulos", "Los nimbostratos"]'::jsonb, 0, 'Los cirrostratos producen halos por la refracción y la reflexión de la luz en sus cristales de hielo; los altoestratos no producen halos (pp. 44-45).', 'pp. 44-45', 'practica', false),
  ('30000003-0000-4000-8102-000000000041', '30000003-0000-4000-8101-000000000011', 'previa', 'De día, en la costa, ¿hacia dónde sopla la brisa?', '["De la tierra hacia el mar", "Paralela a la línea de costa", "Del mar hacia la tierra", "En calma, sin dirección fija"]'::jsonb, 2, 'De día la tierra se calienta más que el mar, la presión en tierra baja y el aire va del mar a tierra: es la brisa de mar (pp. 51-52).', 'pp. 51-52', 'practica', false),
  ('30000003-0000-4000-8102-000000000042', '30000003-0000-4000-8101-000000000011', 'comprobacion', '¿Qué es la visibilidad reinante que se cifra en el METAR?', '["El menor valor observado en cualquier dirección del horizonte del aeródromo", "La media de las visibilidades medidas en las cuatro direcciones principales", "La distancia a la que el piloto ve las luces del eje de la pista en uso", "El mayor valor alcanzado en al menos la mitad del horizonte o del aeródromo"]'::jsonb, 3, 'La visibilidad reinante es el valor máximo alcanzado dentro de un círculo que cubre al menos la mitad del horizonte o de la superficie del aeródromo. Si fluctúa mucho, se cifra la mínima (pp. 48-49).', 'pp. 48-49', 'practica', false),
  ('30000003-0000-4000-8102-000000000043', '30000003-0000-4000-8101-000000000011', 'comprobacion', '¿Qué nubes dan precipitación en forma de chubasco?', '["Las de desarrollo vertical, sobre todo los Cb", "Las estratiformes, sobre todo los As y los Ns", "Las altas, sobre todo los cirros y cirrostratos", "Las bajas, sobre todo los estratos y los Sc"]'::jsonb, 0, 'Los Cb, y a veces los Cu muy desarrollados, dan precipitación intensa en chubasco. As y Ns dan precipitación continua (p. 49).', 'p. 49', 'practica', false),
  ('30000003-0000-4000-8102-000000000044', '30000003-0000-4000-8101-000000000011', 'comprobacion', '¿Qué límite de viento cruzado toleran las aeronaves, según el temario?', '["Entre 5 y 10 kt", "Entre 15 y 35 kt", "Entre 40 y 60 kt", "Entre 60 y 80 kt"]'::jsonb, 1, 'El límite máximo de componente transversal varía entre 15 y 35 kt según el tipo de aeronave y el estado de la pista (p. 51).', 'p. 51', 'practica', false),
  ('30000003-0000-4000-8102-000000000045', '30000003-0000-4000-8101-000000000012', 'previa', '¿Qué fenómeno suele reducir más la visibilidad?', '["La niebla", "La calima", "El smog", "La ventisca"]'::jsonb, 0, 'De todos los fenómenos que reducen la visibilidad en superficie, el que normalmente más influye es la niebla (p. 54).', 'p. 54', 'practica', false),
  ('30000003-0000-4000-8102-000000000046', '30000003-0000-4000-8101-000000000012', 'comprobacion', 'Para el RVR, ¿a qué altura sobre el eje de la pista se considera al piloto?', '["A 2,5 m", "A 1 m", "A 5 m", "A 9 m"]'::jsonb, 2, 'El RVR mide hasta dónde ve las señales o luces de la pista un piloto a 5 m sobre el eje. Los transmisómetros están a 2,5 m del suelo (p. 54).', 'p. 54', 'practica', false),
  ('30000003-0000-4000-8102-000000000047', '30000003-0000-4000-8101-000000000012', 'comprobacion', 'La visibilidad es de 3.000 m, con humedad relativa del 80 %. ¿Qué es, según el temario?', '["Neblina", "Niebla", "Niebla baja", "Calima"]'::jsonb, 0, 'Si la reducción de visibilidad es superior a 1.000 m con humedad relativa superior al 70 %, se llama neblina. La niebla deja menos de 1.000 m (p. 55).', 'p. 55', 'practica', false),
  ('30000003-0000-4000-8102-000000000048', '30000003-0000-4000-8101-000000000012', 'comprobacion', '¿Cuál es el engelamiento más peligroso para las aeronaves?', '["El hielo granulado", "El hielo claro", "La lluvia engelante", "El depósito de escarcha"]'::jsonb, 2, 'La lluvia engelante es el engelamiento más peligroso: es hielo transparente y las gotas se congelan uniformemente por todo el avión (p. 58).', 'p. 58', 'practica', false),
  ('30000003-0000-4000-8102-000000000049', '30000003-0000-4000-8101-000000000013', 'previa', '¿Qué es la cizalladura del viento?', '["Un cambio de velocidad o dirección del viento entre dos puntos próximos", "Un viento constante que sopla paralelo al eje de una cadena montañosa", "Un descenso de aire frío y denso hacia el suelo desde capas altas", "Una corriente de aire fuerte y estrecha en la alta troposfera"]'::jsonb, 0, 'La cizalladura es un cambio en la velocidad o la dirección del viento entre dos puntos próximos; puede ser horizontal, vertical o ambas (p. 59).', 'p. 59', 'practica', false),
  ('30000003-0000-4000-8102-000000000050', '30000003-0000-4000-8101-000000000013', 'comprobacion', '¿En qué frentes suele ser mayor la turbulencia?', '["En los frentes cálidos", "En los estacionarios", "En los frentes fríos", "En los ocluidos"]'::jsonb, 2, 'Generalmente la turbulencia es mayor en los frentes fríos que en los cálidos, y aumenta si hay convección y vientos fuertes (p. 62).', 'p. 62', 'practica', false),
  ('30000003-0000-4000-8102-000000000051', '30000003-0000-4000-8101-000000000013', 'comprobacion', '¿Qué intensidad de turbulencia deja el avión prácticamente ingobernable?', '["Fuerte", "Moderada", "Extrema", "Ligera"]'::jsonb, 2, 'En la turbulencia extrema el avión es zarandeado violentamente y es prácticamente ingobernable (p. 60).', 'p. 60', 'practica', false),
  ('30000003-0000-4000-8102-000000000052', '30000003-0000-4000-8101-000000000013', 'comprobacion', '¿Dónde aparece con más frecuencia la turbulencia en aire claro (TAC)?', '["En capas bajas inestables, dentro de cumulonimbos en desarrollo", "Sobre la pista, justo después del despegue de un avión pesado", "En días calurosos, sobre superficies muy calientes del terreno", "En capas estables de niveles altos, con fuerte cizalladura vertical"]'::jsonb, 3, 'La TAC aparece en vuelos de alta cota, a menudo fuera de nubes, sobre todo en capas estables de niveles altos con fuerte cizalladura vertical y cerca de la corriente en chorro (p. 63).', 'p. 63', 'practica', false),
  ('30000003-0000-4000-8102-000000000053', '30000003-0000-4000-8101-000000000014', 'previa', '¿Qué nube tiene que haber para que se produzca una tormenta?', '["El cumulonimbo", "El nimbostrato", "El altocúmulo", "El cirrostrato"]'::jsonb, 0, 'Una tormenta se produce cuando hay cumulonimbos acompañados de aparato eléctrico (rayos y truenos) (p. 64).', 'p. 64', 'practica', false),
  ('30000003-0000-4000-8102-000000000054', '30000003-0000-4000-8101-000000000014', 'comprobacion', '¿En qué fase de la tormenta desaparecen las corrientes ascendentes?', '["En la fase de madurez", "En la fase de formación", "En la fase de disipación", "En la fase de crecimiento"]'::jsonb, 2, 'La disipación empieza cuando desaparecen las ascendentes; las descendentes se extienden y se suavizan (p. 66).', 'p. 66', 'practica', false),
  ('30000003-0000-4000-8102-000000000055', '30000003-0000-4000-8101-000000000014', 'comprobacion', '¿Qué anchura puede tener una línea de turbonada?', '["De 1 a 5 km", "De 20 a 50 km", "De 100 a 200 km", "Menos de 1 km"]'::jsonb, 1, 'Una línea de turbonada puede medir cientos de kilómetros de largo y de 20 a 50 km de ancho, y se desplaza a unos 25 kt de media (p. 67).', 'p. 67', 'practica', false),
  ('30000003-0000-4000-8102-000000000056', '30000003-0000-4000-8101-000000000014', 'comprobacion', '¿Cómo se llama un ciclón tropical con vientos máximos en superficie de hasta 33 kt?', '["Tormenta tropical", "Perturbación tropical", "Tifón del Pacífico", "Depresión tropical"]'::jsonb, 3, 'Perturbación tropical: vientos ligeros. Depresión tropical: hasta 33 kt. Tormenta tropical: de 34 a 63 kt. Huracán, ciclón o tifón: más de 64 kt (p. 70).', 'p. 70', 'practica', false)
insert into public.concept_cards (id, block_id, front, back, term_en, source_pages, reviewed) values
  ('30000003-0000-4000-8103-000000000001', '30000003-0000-4000-8101-000000000001', '¿Qué Anexo de la OACI regula el servicio meteorológico aeronáutico?', 'El Anexo 3. La OACI trabaja en cooperación con la OMM, organismo especializado de la ONU.', null, 'p. 5', false),
  ('30000003-0000-4000-8103-000000000002', '30000003-0000-4000-8101-000000000001', '¿Cuántos WAFC hay y dónde están?', 'Dos: Londres y Washington. Si uno interrumpe su actividad, el otro asume sus funciones.', 'World Area Forecast Centre (WAFC)', 'p. 7', false),
  ('30000003-0000-4000-8103-000000000003', '30000003-0000-4000-8101-000000000001', '¿Cuántos VAAC, TCAC y CMRE hay?', '9 VAAC (cenizas volcánicas), 7 TCAC (ciclones tropicales) y 8 CMRE (materiales radiactivos).', null, 'p. 7', false),
  ('30000003-0000-4000-8103-000000000004', '30000003-0000-4000-8101-000000000001', '¿Qué diferencia hay entre EMAe y OMAe?', 'EMAe: observan (METAR y SPECI) en 40 aeropuertos de Aena y 8 bases aéreas. OMAe: predicen (TAF, TREND y avisos); hay 5: Las Palmas, Madrid, Santander, Sevilla y Valencia.', null, 'p. 8', false),
  ('30000003-0000-4000-8103-000000000005', '30000003-0000-4000-8101-000000000001', '¿Qué oficinas de vigilancia meteorológica hay en España?', 'Dos, de AEMET: Valencia (FIR Madrid y FIR Barcelona) y Las Palmas de Gran Canaria (FIR Canarias).', null, 'p. 8', false),
  ('30000003-0000-4000-8103-000000000006', '30000003-0000-4000-8101-000000000002', 'Composición del aire seco cerca del nivel del mar', '78 % nitrógeno (N2), 21 % oxígeno (O2) y 1 % otros gases (Ar, Ne, CO2, H2, O3…).', null, 'p. 10', false),
  ('30000003-0000-4000-8103-000000000007', '30000003-0000-4000-8101-000000000002', '¿Cuánto vapor de agua puede haber en la atmósfera y dónde está?', 'Entre el 0,2 % y el 3 %, casi todo en la troposfera.', 'water vapour', 'p. 11', false),
  ('30000003-0000-4000-8103-000000000008', '30000003-0000-4000-8101-000000000002', '¿De qué dos formas se satura un volumen de aire?', 'Enfriándolo o inyectándole vapor de agua.', null, 'p. 17', false),
  ('30000003-0000-4000-8103-000000000009', '30000003-0000-4000-8101-000000000002', 'Humedad relativa', 'Cociente entre el vapor que contiene el aire y el máximo que admite a la misma temperatura. Aire saturado: 100 %.', 'relative humidity', 'p. 17', false),
  ('30000003-0000-4000-8103-000000000010', '30000003-0000-4000-8101-000000000002', 'Punto de rocío', 'Temperatura a la que hay que enfriar el aire, a presión constante, para saturarlo. Si la temperatura se acerca a él, puede haber niebla.', 'dew point', 'p. 18', false),
  ('30000003-0000-4000-8103-000000000011', '30000003-0000-4000-8101-000000000003', '¿Cuánto baja la presión en los primeros metros de altitud?', 'Alrededor de 1 mb cada 9 m (30 ft), de forma aproximadamente lineal. Después, la caída es exponencial.', null, 'p. 13', false),
  ('30000003-0000-4000-8103-000000000012', '30000003-0000-4000-8101-000000000003', 'Variación diaria de la presión', 'Dos máximos, hacia las 10 y las 22 h, y dos mínimos, hacia las 4 y las 16 h. En zonas templadas es menor de 1 hPa.', null, 'p. 13', false),
  ('30000003-0000-4000-8103-000000000013', '30000003-0000-4000-8101-000000000003', 'Equivalencia de unidades de presión', '1 atm = 760 mm Hg = 1013,25 hPa (mb).', null, 'p. 14', false),
  ('30000003-0000-4000-8103-000000000014', '30000003-0000-4000-8101-000000000003', 'Fórmulas para convertir temperaturas', 'C = 5/9 · (F − 32) y K = C + 273.', null, 'p. 16', false),
  ('30000003-0000-4000-8103-000000000015', '30000003-0000-4000-8101-000000000003', '¿Cuándo se dan el máximo y el mínimo diarios de temperatura?', 'El máximo, unas dos horas después del mediodía; el mínimo, poco después del amanecer, por la inercia térmica.', null, 'p. 15', false),
  ('30000003-0000-4000-8103-000000000016', '30000003-0000-4000-8101-000000000004', 'Altura de la tropopausa según la latitud', 'Unos 8 km en latitudes altas, 12 km en latitudes medias y 18 km en latitudes bajas.', 'tropopause', 'p. 18', false),
  ('30000003-0000-4000-8103-000000000017', '30000003-0000-4000-8101-000000000004', '¿Qué le pasa a la temperatura en la estratosfera?', 'Sube con la altitud, sobre todo por la abundancia de ozono. La capa llega hasta unos 50-55 km.', 'stratosphere', 'p. 18', false),
  ('30000003-0000-4000-8103-000000000018', '30000003-0000-4000-8101-000000000004', '¿Cuál es el nivel más frío de la atmósfera?', 'La mesopausa, techo de la mesosfera (unos −95 ºC, a unos 80 km).', null, 'p. 19', false),
  ('30000003-0000-4000-8103-000000000019', '30000003-0000-4000-8101-000000000004', 'Gradiente térmico positivo y negativo', 'Positivo: la temperatura desciende con la altura. Negativo: la temperatura aumenta con la altura.', null, 'p. 15', false),
  ('30000003-0000-4000-8103-000000000020', '30000003-0000-4000-8101-000000000004', 'Aire estable frente a aire inestable', 'Estable: cielo despejado o estratiformes, nieblas y humo que reduce la visibilidad. Inestable: nubes desarrolladas, chubascos, turbulencia y buena visibilidad fuera de ellos.', null, 'p. 21', false),
  ('30000003-0000-4000-8103-000000000021', '30000003-0000-4000-8101-000000000005', 'Valores ISA a nivel del mar', '15 ºC (288,15 K), 1013,25 hPa (760 mm Hg) y 1,2250 kg/m³.', 'International Standard Atmosphere (ISA)', 'p. 21', false),
  ('30000003-0000-4000-8103-000000000022', '30000003-0000-4000-8101-000000000005', 'Gradiente térmico ISA en la troposfera', '2 ºC cada 1.000 ft (6,5 ºC cada 1.000 m), hasta unos −56,5 ºC en la tropopausa.', null, 'p. 22', false),
  ('30000003-0000-4000-8103-000000000023', '30000003-0000-4000-8101-000000000005', 'Altura, altitud y elevación', 'Altura: sobre una superficie de referencia, normalmente el suelo. Altitud: sobre el nivel medio del mar. Elevación: de un punto del terreno sobre el nivel medio del mar.', null, 'p. 23', false),
  ('30000003-0000-4000-8103-000000000024', '30000003-0000-4000-8101-000000000005', 'QNH', 'Presión del aeródromo reducida al nivel del mar en condiciones ISA. El altímetro indica altitud; en tierra, la del aeródromo.', null, 'p. 25', false),
  ('30000003-0000-4000-8103-000000000025', '30000003-0000-4000-8101-000000000005', 'QFE', 'Presión medida en el aeródromo. El altímetro indica altura; en tierra, cero.', null, 'p. 25', false),
  ('30000003-0000-4000-8103-000000000026', '30000003-0000-4000-8101-000000000005', 'QNE', 'Presión estándar de 1013,25 hPa. Todos los aviones en ruta la usan y así vuelan en niveles de vuelo.', null, 'p. 25', false),
  ('30000003-0000-4000-8103-000000000027', '30000003-0000-4000-8101-000000000006', 'Nivel de vuelo', 'Superficie de presión constante referida a 1013,25 hPa (ISA), expresada en centenares de pies. Siempre queda por encima de la altitud de transición.', 'flight level', 'p. 25', false),
  ('30000003-0000-4000-8103-000000000028', '30000003-0000-4000-8101-000000000006', 'Altitud de transición', 'Por debajo se vuela en altitudes (QNH); por encima, en niveles de vuelo (QNE). Se usa en el despegue y es fija para cada aeropuerto.', 'transition altitude', 'p. 26', false),
  ('30000003-0000-4000-8103-000000000029', '30000003-0000-4000-8101-000000000006', 'Nivel de transición', 'Nivel de vuelo más bajo disponible por encima de la altitud de transición. Se usa en la aproximación y depende de la meteorología.', 'transition level', 'p. 26', false),
  ('30000003-0000-4000-8103-000000000030', '30000003-0000-4000-8101-000000000006', 'Capa de transición', 'Capa entre el nivel y la altitud de transición. Su espesor es variable y siempre de 1.000 ft o más.', 'transition layer', 'p. 26', false),
  ('30000003-0000-4000-8103-000000000031', '30000003-0000-4000-8101-000000000006', 'Altitudes de transición en España', 'TMA de Madrid: 13.000 ft. CTA de Granada: 7.000 ft. Resto: 6.000 ft.', null, 'p. 26', false),
  ('30000003-0000-4000-8103-000000000032', '30000003-0000-4000-8101-000000000007', '¿Cómo se reparte la radiación solar?', '36 % nubes (absorción o reflejo), 20 % gases (5 % ozono y 15 % CO2), 4 % reflejo de la superficie y 40 % absorción de la superficie.', null, 'p. 27', false),
  ('30000003-0000-4000-8103-000000000033', '30000003-0000-4000-8101-000000000007', 'Radiación solar y radiación terrestre', 'Solar: onda corta, procedente del Sol. Terrestre: onda larga, emitida por la superficie, los gases, los aerosoles y las nubes.', null, 'pp. 27-28', false),
  ('30000003-0000-4000-8103-000000000034', '30000003-0000-4000-8101-000000000007', 'Convección', 'Transmisión de calor mediante un fluido. En meteorología origina con frecuencia los movimientos verticales del aire.', 'convection', 'p. 30', false),
  ('30000003-0000-4000-8103-000000000035', '30000003-0000-4000-8101-000000000007', 'Advección', 'Transmisión de calor con movimientos horizontales de masas de aire. Es importante en la formación de nubes orográficas.', 'advection', 'p. 30', false),
  ('30000003-0000-4000-8103-000000000036', '30000003-0000-4000-8101-000000000007', 'Calor específico del agua', 'Es el mayor de la naturaleza: el mar se calienta y se enfría más despacio que la tierra.', null, 'p. 27', false),
  ('30000003-0000-4000-8103-000000000037', '30000003-0000-4000-8101-000000000008', 'Las tres células de la circulación general', 'Hadley (del ecuador a 30º), Ferrel (de 30º a 60º) y Polar (de 60º al polo).', null, 'p. 32', false),
  ('30000003-0000-4000-8103-000000000038', '30000003-0000-4000-8101-000000000008', 'Fuerza de Coriolis', 'Desvía los objetos en movimiento a la derecha en el hemisferio norte y a la izquierda en el sur.', 'Coriolis force', 'p. 33', false),
  ('30000003-0000-4000-8103-000000000039', '30000003-0000-4000-8101-000000000008', 'Alisios', 'Soplan de la alta subtropical a la vaguada ecuatorial: del NE en el hemisferio norte y del SE en el sur. Convergen en la Zona de Convergencia Intertropical.', 'trade winds', 'p. 35', false),
  ('30000003-0000-4000-8103-000000000040', '30000003-0000-4000-8101-000000000008', 'Corriente en chorro', 'Corriente fuerte y estrecha en la alta troposfera o la estratosfera, con fuerte cizalladura. Circula de oeste a este y forma ondulaciones (ondas de Rossby).', 'jet stream', 'p. 35', false),
  ('30000003-0000-4000-8103-000000000041', '30000003-0000-4000-8101-000000000008', 'Convergencia y divergencia', 'Convergencia: dos corrientes se encuentran y comprimen la masa de aire. Divergencia: la masa de aire se separa.', null, 'p. 34', false),
  ('30000003-0000-4000-8103-000000000042', '30000003-0000-4000-8101-000000000009', 'Anticiclón', 'Presión más alta que alrededor. En el hemisferio norte gira en sentido horario, con viento flojo en el centro. Tiempo estable; favorece las nieblas en invierno.', 'anticyclone', 'pp. 36-37', false),
  ('30000003-0000-4000-8103-000000000043', '30000003-0000-4000-8101-000000000009', 'Depresión o borrasca', 'Presión mucho más baja que alrededor. En el hemisferio norte gira en sentido antihorario, con viento normalmente fuerte en el centro.', 'depression', 'p. 37', false),
  ('30000003-0000-4000-8103-000000000044', '30000003-0000-4000-8101-000000000009', 'DANA', 'Depresión aislada en niveles altos (antes «gota fría»): aire frío en altura, de 200 km o más, con trayectoria difícil de predecir y lluvias intensas.', null, 'p. 38', false),
  ('30000003-0000-4000-8103-000000000045', '30000003-0000-4000-8101-000000000009', 'Clasificación de las masas de aire', 'Por temperatura: ártica, polar, tropical o ecuatorial. Por humedad: seca (continental) o húmeda (marítima). En total, 8 tipos.', 'air mass', 'p. 39', false),
  ('30000003-0000-4000-8103-000000000046', '30000003-0000-4000-8101-000000000009', 'Tipos de frente', 'Frío (empuja el frío), cálido (empuja el caliente), estacionario (no hay desplazamiento) y ocluido (el frío alcanza al cálido).', 'front', 'pp. 40-41', false),
  ('30000003-0000-4000-8103-000000000047', '30000003-0000-4000-8101-000000000010', 'Condiciones para que se formen nubes', 'Humedad relativa alta, un mecanismo que lleve el aire a la saturación (sobre todo el enfriamiento) y núcleos de condensación.', null, 'p. 41', false),
  ('30000003-0000-4000-8103-000000000048', '30000003-0000-4000-8101-000000000010', 'Familias de nubes', 'Altas: Ci, Cs y Cc. Medias: Ac, Ns y As. Bajas: St y Sc. De desarrollo vertical: Cu y Cb.', null, 'p. 43', false),
  ('30000003-0000-4000-8103-000000000049', '30000003-0000-4000-8101-000000000010', 'FEW, SCT, BKN y OVC', 'FEW: 1-2 octas. SCT: 3-4 octas. BKN: 5-7 octas. OVC: cielo cubierto.', null, 'p. 46', false),
  ('30000003-0000-4000-8103-000000000050', '30000003-0000-4000-8101-000000000010', 'Techo de nubes', 'Altura sobre el suelo de la base de la capa más baja que cubre más de la mitad del cielo (BKN u OVC) y está por debajo de 20.000 ft (6.000 m).', 'ceiling', 'p. 47', false),
  ('30000003-0000-4000-8103-000000000051', '30000003-0000-4000-8101-000000000010', 'CAVOK', 'Sin nubes, sin fenómenos significativos y con visibilidad de más de 10 km.', 'CAVOK', 'p. 46', false),
  ('30000003-0000-4000-8103-000000000052', '30000003-0000-4000-8101-000000000010', 'Nube de importancia para las operaciones', 'La de base por debajo del mayor valor entre 1.500 m (5.000 ft) y la altitud mínima de sector más alta, o cualquier Cb o cúmulo de desarrollo vertical.', null, 'p. 47', false),
  ('30000003-0000-4000-8103-000000000053', '30000003-0000-4000-8101-000000000011', 'Visibilidad en sentido aeronáutico', 'El mayor valor entre la distancia a la que se ve un objeto negro ante un fondo brillante (MOR, de día) y la distancia a la que se ven luces de unas 1.000 candelas (de noche).', 'visibility', 'p. 47', false),
  ('30000003-0000-4000-8103-000000000054', '30000003-0000-4000-8101-000000000011', '¿Cómo se expresa el viento?', 'Dirección: de procedencia, en grados desde el norte verdadero y en sentido horario. Intensidad: en nudos.', null, 'p. 51', false),
  ('30000003-0000-4000-8103-000000000055', '30000003-0000-4000-8101-000000000011', 'Chubasco', 'Precipitación que empieza y acaba bruscamente, relativamente intensa y breve, de gotas grandes y nubes convectivas.', 'shower', 'p. 49', false),
  ('30000003-0000-4000-8103-000000000056', '30000003-0000-4000-8101-000000000011', 'Efectos de la precipitación en las operaciones', 'Reduce la visibilidad, genera cizalladura, provoca engelamiento bajo 0 ºC, empeora el frenado (aquaplaning) y alarga el rodaje y la ocupación de pista.', null, 'p. 50', false),
  ('30000003-0000-4000-8103-000000000057', '30000003-0000-4000-8101-000000000011', 'Brisa de mar y brisa de tierra', 'De día, del mar a tierra, porque la tierra se calienta más. De noche, de tierra al mar.', null, 'pp. 51-52', false),
  ('30000003-0000-4000-8103-000000000058', '30000003-0000-4000-8101-000000000011', 'Efecto Foehn', 'A sotavento, el aire que baja se calienta por compresión adiabática y llega más cálido y seco que a la misma altura en barlovento.', null, 'pp. 52-53', false),
  ('30000003-0000-4000-8103-000000000059', '30000003-0000-4000-8101-000000000012', '¿Cuándo se cifra el RVR y cómo se obtiene?', 'Cuando la visibilidad es inferior a 1.500 m. Es el promedio de los 10 minutos anteriores, medido con transmisómetros a 2,5 m de altura y a unos 100 m del eje, en la zona de toma de contacto.', 'Runway Visual Range (RVR)', 'p. 54', false),
  ('30000003-0000-4000-8103-000000000060', '30000003-0000-4000-8101-000000000012', 'Niebla, neblina y bruma', 'Niebla: visibilidad inferior a 1.000 m. Neblina: superior a 1.000 m con humedad relativa superior al 70 %. Bruma: neblina por partículas, sobre todo de sal, típica de costa.', null, 'p. 55', false),
  ('30000003-0000-4000-8103-000000000061', '30000003-0000-4000-8101-000000000012', 'Intensidad del engelamiento', 'Ligero: sin problemas salvo si dura mucho. Moderado: rápido, pero los equipos de a bordo lo eliminan. Fuerte: los equipos no bastan; cambio de altitud inmediato.', null, 'p. 57', false),
  ('30000003-0000-4000-8103-000000000062', '30000003-0000-4000-8101-000000000012', 'Hielo claro y hielo granulado', 'Claro: transparente, liso, muy adherente y muy peligroso (aire de 0 a −10 ºC). Granulado: blanco, opaco, rugoso y poco adherente (aire de 0 a −40 ºC).', null, 'p. 58', false),
  ('30000003-0000-4000-8103-000000000063', '30000003-0000-4000-8101-000000000012', 'Lluvia engelante', 'Gotas de una capa por encima de 0 ºC que se sobreenfrían al cruzar capas por debajo de 0 ºC. Es el engelamiento más peligroso.', 'freezing rain', 'p. 58', false),
  ('30000003-0000-4000-8103-000000000064', '30000003-0000-4000-8101-000000000012', 'Ilusiones ópticas', 'Pueden hacer creer al piloto que vuela a otra altura o distancia. Las causan, entre otras, la pendiente y la anchura de la pista, el terreno, el agua en el parabrisas y la falta de contraste de las luces.', null, 'p. 56', false),
  ('30000003-0000-4000-8103-000000000065', '30000003-0000-4000-8101-000000000013', 'Cizalladura del viento', 'Cambio de velocidad o dirección del viento entre dos puntos próximos. Es más fuerte cuanto menor es la distancia y más rápido el cambio.', 'wind shear', 'p. 59', false),
  ('30000003-0000-4000-8103-000000000066', '30000003-0000-4000-8101-000000000013', '¿Qué fenómenos producen cizalladura?', 'Tormentas (microrreventones y frentes de racha), tornados, frentes fríos o cálidos, vientos fuertes con relieve local e inversiones térmicas cerca del suelo.', null, 'p. 59', false),
  ('30000003-0000-4000-8103-000000000067', '30000003-0000-4000-8101-000000000013', 'Condiciones de la onda de montaña', 'Viento en la cima de más de 15 kt y creciente con la altura, dirección constante a menos de 30º de la perpendicular al eje y capa estable sobre la cima.', 'mountain wave', 'p. 62', false),
  ('30000003-0000-4000-8103-000000000068', '30000003-0000-4000-8101-000000000013', 'Turbulencia de estela', 'Remolinos que dejan los aviones y que tardan en disiparse; dependen del tamaño, la velocidad y la configuración de las alas. Tras un avión pesado, autorizar enseguida otro despegue puede ser peligroso.', 'wake turbulence', 'p. 61', false),
  ('30000003-0000-4000-8103-000000000069', '30000003-0000-4000-8101-000000000013', 'Turbulencia en aire claro (TAC)', 'En vuelos a gran altura, a menudo fuera de nubes: capas estables altas con fuerte cizalladura y zonas cercanas a la corriente en chorro. En general es ligera.', 'clear air turbulence (CAT)', 'p. 63', false),
  ('30000003-0000-4000-8103-000000000070', '30000003-0000-4000-8101-000000000014', 'Condiciones para que se forme una tormenta', 'Calor (sobre todo en superficie), atmósfera inestable, humedad suficiente y, a veces, un mecanismo de elevación.', 'thunderstorm', 'p. 64', false),
  ('30000003-0000-4000-8103-000000000071', '30000003-0000-4000-8101-000000000014', 'Fases de una tormenta', 'Formación (ascendentes), madurez (precipitación, descendentes, frente de racha y ascendentes al máximo) y disipación (desaparecen las ascendentes). Vida: de 2 a 3 horas.', null, 'pp. 65-66', false),
  ('30000003-0000-4000-8103-000000000072', '30000003-0000-4000-8101-000000000014', 'Microrreventón', 'Descendente de aire frío y denso de hasta 60 kt desde una nube convectiva. Abarca hasta 5 km, dura de 1 a 5 minutos (nunca más de 15) y da vientos de hasta 150 kt. Puede ser húmedo o seco.', 'microburst', 'pp. 67-68', false),
  ('30000003-0000-4000-8103-000000000073', '30000003-0000-4000-8101-000000000014', 'Escala de los ciclones tropicales', 'Perturbación tropical (vientos ligeros), depresión tropical (hasta 33 kt), tormenta tropical (34 a 63 kt) y huracán, ciclón o tifón (más de 64 kt).', null, 'p. 70', false),
  ('30000003-0000-4000-8103-000000000074', '30000003-0000-4000-8101-000000000014', 'Temperaturas elevadas', 'Por encima de 30 ºC baja la densidad del aire: hacen falta pistas más largas o reducir el peso máximo autorizado para despegar.', null, 'p. 70', false)
insert into public.glossary_terms (id, term, term_en, definition, topic_id, block_id, source_id, source_pages, reviewed) values
  ('30000003-0000-4000-8104-000000000001', 'Tiempo', 'weather', 'Estado de la atmósfera en un instante dado (OMM).', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000001', '30000003-0000-4000-8100-000000000001', 'p. 4', false),
  ('30000003-0000-4000-8104-000000000002', 'Clima', 'climate', 'Síntesis de las condiciones meteorológicas de un lugar, con estadísticas a largo plazo (OMM).', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000001', '30000003-0000-4000-8100-000000000001', 'p. 4', false),
  ('30000003-0000-4000-8104-000000000003', 'VAAC', 'Volcanic Ash Advisory Centre', 'Centro de avisos de cenizas volcánicas. Hay nueve y vigilan las 24 horas.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000001', '30000003-0000-4000-8100-000000000001', 'p. 7', false),
  ('30000003-0000-4000-8104-000000000004', 'OMAe', null, 'Oficina meteorológica de aeródromo: vigilancia y predicciones (TAF, TREND y avisos). En España hay cinco.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000001', '30000003-0000-4000-8100-000000000001', 'p. 8', false),
  ('30000003-0000-4000-8104-000000000005', 'Aire húmedo', null, 'Mezcla de aire seco y vapor de agua.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000002', '30000003-0000-4000-8100-000000000001', 'p. 11', false),
  ('30000003-0000-4000-8104-000000000006', 'Saturación', null, 'Estado del aire que contiene la máxima cantidad de vapor que admite a su temperatura.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000002', '30000003-0000-4000-8100-000000000001', 'p. 17', false),
  ('30000003-0000-4000-8104-000000000007', 'Punto de rocío', 'dew point', 'Temperatura a la que hay que enfriar el aire, a presión constante, para saturarlo.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000002', '30000003-0000-4000-8100-000000000001', 'p. 18', false),
  ('30000003-0000-4000-8104-000000000008', 'Presión atmosférica', 'atmospheric pressure', 'Peso de la columna de aire sobre una superficie hasta el límite de la atmósfera. Se ejerce igual en todas direcciones.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000003', '30000003-0000-4000-8100-000000000001', 'p. 12', false),
  ('30000003-0000-4000-8104-000000000009', 'Densidad', 'density', 'Masa de un gas por unidad de volumen (ρ = m/V).', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000003', '30000003-0000-4000-8100-000000000001', 'p. 16', false),
  ('30000003-0000-4000-8104-000000000010', 'Inercia térmica', null, 'Tiempo que tarda el aire en calentarse o enfriarse; por eso el máximo de temperatura no llega al mediodía.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000003', '30000003-0000-4000-8100-000000000001', 'p. 15', false),
  ('30000003-0000-4000-8104-000000000011', 'Tropopausa', 'tropopause', 'Límite superior de la troposfera, donde la temperatura se mantiene en torno a −56 ºC.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000004', '30000003-0000-4000-8100-000000000001', 'p. 18', false),
  ('30000003-0000-4000-8104-000000000012', 'Homosfera', null, 'Zona de composición homogénea que forman la troposfera, la estratosfera y la mesosfera.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000004', '30000003-0000-4000-8100-000000000001', 'p. 19', false),
  ('30000003-0000-4000-8104-000000000013', 'Estabilidad', 'stability', 'Capacidad de una masa de aire de resistirse al desplazamiento vertical.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000004', '30000003-0000-4000-8100-000000000001', 'p. 21', false),
  ('30000003-0000-4000-8104-000000000014', 'Altitud', 'altitude', 'Distancia vertical entre un punto en el aire y el nivel medio del mar (MSL).', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000005', '30000003-0000-4000-8100-000000000001', 'p. 23', false),
  ('30000003-0000-4000-8104-000000000015', 'Altura', 'height', 'Distancia vertical entre un punto en el aire y una superficie de referencia, normalmente el suelo.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000005', '30000003-0000-4000-8100-000000000001', 'p. 23', false),
  ('30000003-0000-4000-8104-000000000016', 'Elevación', 'elevation', 'Distancia vertical entre un punto del terreno y el nivel medio del mar.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000005', '30000003-0000-4000-8100-000000000001', 'p. 23', false),
  ('30000003-0000-4000-8104-000000000017', 'Nivel de vuelo', 'flight level', 'Superficie de presión constante referida a 1013,25 hPa, expresada en centenares de pies.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000006', '30000003-0000-4000-8100-000000000001', 'p. 25', false),
  ('30000003-0000-4000-8104-000000000018', 'Altitud de transición', 'transition altitude', 'Altitud por debajo de la cual la posición vertical se controla en altitudes (QNH) y por encima en niveles de vuelo (QNE).', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000006', '30000003-0000-4000-8100-000000000001', 'p. 26', false),
  ('30000003-0000-4000-8104-000000000019', 'Capa de transición', 'transition layer', 'Capa entre el nivel de transición y la altitud de transición; de 1.000 ft o más.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000006', '30000003-0000-4000-8100-000000000001', 'p. 26', false),
  ('30000003-0000-4000-8104-000000000020', 'Conducción', 'conduction', 'Transmisión de calor por contacto entre dos cuerpos a distinta temperatura.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000007', '30000003-0000-4000-8100-000000000001', 'p. 30', false),
  ('30000003-0000-4000-8104-000000000021', 'Convección', 'convection', 'Transmisión de calor mediante un fluido; origina movimientos verticales del aire.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000007', '30000003-0000-4000-8100-000000000001', 'p. 30', false),
  ('30000003-0000-4000-8104-000000000022', 'Advección', 'advection', 'Transmisión de calor con movimientos horizontales de masas de aire.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000007', '30000003-0000-4000-8100-000000000001', 'p. 30', false),
  ('30000003-0000-4000-8104-000000000023', 'Efecto invernadero', 'greenhouse effect', 'Calentamiento debido a gases transparentes a la onda corta del Sol y absorbentes de la onda larga de la Tierra.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000007', '30000003-0000-4000-8100-000000000001', 'p. 29', false),
  ('30000003-0000-4000-8104-000000000024', 'Corriente en chorro', 'jet stream', 'Corriente de aire fuerte y estrecha, casi horizontal, en la alta troposfera o la estratosfera.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000008', '30000003-0000-4000-8100-000000000001', 'p. 35', false),
  ('30000003-0000-4000-8104-000000000025', 'Subsidencia', null, 'Descenso del aire hacia el suelo en la troposfera.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000008', '30000003-0000-4000-8100-000000000001', 'p. 35', false),
  ('30000003-0000-4000-8104-000000000026', 'Vaguada ecuatorial', null, 'Zona de baja presión situada en el ecuador.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000008', '30000003-0000-4000-8100-000000000001', 'p. 32', false),
  ('30000003-0000-4000-8104-000000000027', 'Masa de aire', 'air mass', 'Gran volumen de aire (miles de kilómetros) con propiedades homogéneas en horizontal, sobre todo temperatura y humedad.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000009', '30000003-0000-4000-8100-000000000001', 'p. 38', false),
  ('30000003-0000-4000-8104-000000000028', 'Frente', 'front', 'Frontera entre dos masas de aire de distinta temperatura y densidad.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000009', '30000003-0000-4000-8100-000000000001', 'p. 39', false),
  ('30000003-0000-4000-8104-000000000029', 'Región manantial', null, 'Superficie terrestre o marítima donde una masa de aire adquiere sus características.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000009', '30000003-0000-4000-8100-000000000001', 'p. 38', false),
  ('30000003-0000-4000-8104-000000000030', 'Octa', 'okta', 'Cada una de las ocho partes en que se divide el cielo para estimar la nubosidad.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000010', '30000003-0000-4000-8100-000000000001', 'p. 46', false),
  ('30000003-0000-4000-8104-000000000031', 'Techo de nubes', 'ceiling', 'Altura de la base de la capa más baja BKN u OVC por debajo de 20.000 ft (6.000 m).', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000010', '30000003-0000-4000-8100-000000000001', 'p. 47', false),
  ('30000003-0000-4000-8104-000000000032', 'Núcleos de condensación', null, 'Partículas higroscópicas que facilitan la condensación.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000010', '30000003-0000-4000-8100-000000000001', 'p. 41', false),
  ('30000003-0000-4000-8104-000000000033', 'Visibilidad reinante', null, 'Valor máximo de visibilidad alcanzado dentro de un círculo que cubre al menos la mitad del horizonte o del aeródromo.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000011', '30000003-0000-4000-8100-000000000001', 'pp. 48-49', false),
  ('30000003-0000-4000-8104-000000000034', 'Virga', 'virga', 'Precipitación que se evapora antes de llegar al suelo y forma filamentos bajo la nube.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000011', '30000003-0000-4000-8100-000000000001', 'p. 50', false),
  ('30000003-0000-4000-8104-000000000035', 'MOR', 'Meteorological Optical Range', 'Alcance óptico meteorológico: distancia máxima a la que se ve y reconoce un objeto negro ante un fondo brillante.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000011', '30000003-0000-4000-8100-000000000001', 'p. 47', false),
  ('30000003-0000-4000-8104-000000000036', 'RVR', 'Runway Visual Range', 'Alcance visual en pista: distancia hasta la que un piloto sobre el eje ve las señales o las luces de la pista.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000012', '30000003-0000-4000-8100-000000000001', 'pp. 47, 54', false),
  ('30000003-0000-4000-8104-000000000037', 'Niebla', 'fog', 'Nube estratiforme en contacto con el suelo o a muy poca altura que deja la visibilidad por debajo de 1.000 m.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000012', '30000003-0000-4000-8100-000000000001', 'p. 55', false),
  ('30000003-0000-4000-8104-000000000038', 'Neblina', 'mist', 'Reducción de la visibilidad por encima de 1.000 m con humedad relativa superior al 70 %.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000012', '30000003-0000-4000-8100-000000000001', 'p. 55', false),
  ('30000003-0000-4000-8104-000000000039', 'Engelamiento', 'icing', 'Formación de hielo en el avión cuando el agua subfundida se congela al impactar con él.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000012', '30000003-0000-4000-8100-000000000001', 'p. 56', false),
  ('30000003-0000-4000-8104-000000000040', 'Cizalladura', 'wind shear', 'Cambio de velocidad o dirección del viento entre dos puntos próximos.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000013', '30000003-0000-4000-8100-000000000001', 'p. 59', false),
  ('30000003-0000-4000-8104-000000000041', 'Turbulencia', 'turbulence', 'Estado del flujo de aire con fluctuaciones irregulares de velocidad, en forma de remolinos.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000013', '30000003-0000-4000-8100-000000000001', 'p. 60', false),
  ('30000003-0000-4000-8104-000000000042', 'Rotor', 'rotor', 'Torbellino que se forma bajo las crestas de la onda de montaña; el más peligroso, bajo la primera onda.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000013', '30000003-0000-4000-8100-000000000001', 'p. 62', false),
  ('30000003-0000-4000-8104-000000000043', 'Frente de racha', null, 'Ráfagas fuertes en la frontera entre el aire frío de la tormenta y el aire más cálido del entorno.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000013', '30000003-0000-4000-8100-000000000001', 'p. 59', false),
  ('30000003-0000-4000-8104-000000000044', 'Línea de turbonada', 'squall line', 'Línea de tormentas muy activas, de hasta cientos de kilómetros de largo y de 20 a 50 km de ancho.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000014', '30000003-0000-4000-8100-000000000001', 'p. 67', false),
  ('30000003-0000-4000-8104-000000000045', 'Microrreventón', 'microburst', 'Fuerte corriente descendente de aire frío y denso que sale de una nube convectiva.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000014', '30000003-0000-4000-8100-000000000001', 'p. 67', false),
  ('30000003-0000-4000-8104-000000000046', 'Tuba', 'funnel cloud', 'Torbellino de un tornado que no alcanza la superficie terrestre.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000014', '30000003-0000-4000-8100-000000000001', 'p. 68', false),
  ('30000003-0000-4000-8104-000000000047', 'Tromba marina', null, 'Tornado formado sobre el mar, que aspira el agua hasta centenares de metros de altura.', '00000000-0000-4000-8000-000000006003', '30000003-0000-4000-8101-000000000014', '30000003-0000-4000-8100-000000000001', 'p. 68', false)
